class Tag {
    int code;
    Tag(int code) { this.code = code; }
    @Override public int hashCode() { return code; }
    @Override public boolean equals(Object o) { return o instanceof Tag t && t.code == code; }
}

Map<Tag, String> map = new HashMap<>();
Tag tag = new Tag(3);
map.put(tag, "stored");
tag.code = 20;
System.out.println(map.get(tag) + " size=" + map.size());

