class ConstKey {
    final int id;
    ConstKey(int id) { this.id = id; }
    @Override public int hashCode() { return 42; }
    @Override public boolean equals(Object o) { return o instanceof ConstKey k && k.id == id; }
}

Map<ConstKey, String> map = new HashMap<>();
for (int i = 0; i < 100_000; i++) {
    map.put(new ConstKey(i), "v" + i);
}
System.out.println(map.size() + " " + map.get(new ConstKey(99_999)));

