class SessionKey {
    final String user;
    SessionKey(String user) { this.user = user; }
    @Override public int hashCode() { return 1; }
    @Override public boolean equals(Object o) { return o instanceof SessionKey k && k.user.equals(user); }
}

Map<SessionKey, String> sessions = new HashMap<>();
sessions.put(new SessionKey("ann"), "token");
System.out.println(sessions.get(new SessionKey("ann")));

class Point {
    int x;
    Point(int x) { this.x = x; }
    @Override public int hashCode() { return x; }
    @Override public boolean equals(Object o) { return o instanceof Point p && p.x == x; }
}

Map<Point, String> map = new HashMap<>();
Point p = new Point(1);
map.put(p, "a");
p.x = 2;
System.out.println(map.size() + " " + map.get(p));
